th { color: #777; font-weight: 500; border-bottom: 1px solid #e3e3e0; }
.range { margin-top: 12px; }
.range input, .range button { font: inherit; font-size: 14px; padding: 4px 8px; border: 1px solid #ccc; border-radius: 4px; }
.range button { background: #3b6ea5; color: #fff; border-color: #3b6ea5; }
