    and both the nav links and the csv download carry the current date window along,
    so moving between pages or downloading doesn't quietly reset it to the default."""
    qs = f"?start={start}&end={end}"
    links = "".join(f'<a href="{m.PATH}{qs}">{m.TITLE}</a>' for m in discover())
    return f"""<!doctype html>
<html><head><meta charset="utf-8"><title>{title}</title><style>{STYLE}</style></head>
<body>
<header><h1>Fremont Bridge bicycle counter</h1>
<nav>{links}<a href="/daily.csv{qs}">Download CSV</a></nav>
<form method="get" class="range">
<input type="date" name="start" value="{start}">
<input type="date" name="end" value="{end}">
<button type="submit">Apply</button>
</form>
</header>
<main>{body}</main>
</body></html>"""

